#ifndef SRC_EDITOR_EDITOR_NPCSTATS_H
#define SRC_EDITOR_EDITOR_NPCSTATS_H

/**
 * The npc stats LEDGER (docs/NPC_WIKI_STATS_PLAN.md section 4, "Layer 1"):
 * `<content_dir>/npc_stats/<shard>/<gameval>.stats`, one file per attackable
 * spawned npc, written by tools/gen_npc_stats.py and read back by it:
 *
 *     // Goblin (npc 3028) -- combat level 2
 *     // Source: OSRS Wiki "Goblin" revid 14783221, ...
 *     // Generated by tools/gen_npc_stats.py. Re-running rewrites this file.
 *     // To pin a value by hand: edit it, set `source = authored`, and later runs
 *     // read this file back and leave it exactly as it stands.
 *
 *     source        = generated
 *     hitpoints     = 5
 *     attackrate    = 4                    // wiki `attack speed`
 *     crushattack   = -21
 *
 * GRAMMAR (gen_npc_stats.py read_ledger): a line whose first non-blank bytes
 * are "//", or that holds no '=', is text; every other line is `key = value`
 * with an optional trailing `// note`; a value "" or "-" is no value. The
 * shard is the name's first byte lowercased, "_" when it is not a letter or
 * digit (shard_of).
 *
 * The encounter builder's Stats tab edits it as a TEXT document (key
 * "stats:<shard>/<gameval>"). LINE-PRESERVING: parse -> emit is
 * byte-identical; an edit rewrites only the value bytes of its line (its key
 * column, its note and the note's column kept where the value's width
 * allows), adds a missing key after the file's last stat line in that line's
 * key column, and sets `source = authored` -- the one thing that makes the
 * generator leave the file as it stands. Every other byte is kept.
 *
 * Also here: the read-only cells the Stats tab shows beside the inputs. The
 * server's swing is content (torirs_server_combat.c says so: its formulas are
 * `skill_combat/combat_stats.rs2`), so these restate that script's rules as
 * the tree states them, with the formula named in the cell's tooltip.
 *
 * Pure: no document, no host. NULL arguments assert.
 */

#include "editor_cmd.h"

#include <stddef.h>

/** TEXT document keys "stats:<shard>/<gameval>" -> npc_stats/<shard>/<gameval>.stats. */
#define EDITOR_NPCSTATS_KEY_PREFIX "stats:"
#define EDITOR_NPCSTATS_DIR "npc_stats"

/** Bytes of a key / value / note, the terminator included. */
#define EDITOR_NPCSTATS_KEY_MAX 64
#define EDITOR_NPCSTATS_VALUE_MAX 128

enum Editor_NpcStatsLineKind
{
    EDITOR_NPCSTATS_LINE_TEXT = 0,
    EDITOR_NPCSTATS_LINE_FIELD,
};

struct Editor_NpcStatsLine
{
    enum Editor_NpcStatsLineKind kind;
    /** Owned: the line's bytes without its '\n' (a CR kept). */
    char* text;
    /** FIELD: the key, trimmed. */
    char key[EDITOR_NPCSTATS_KEY_MAX];
    /** FIELD: the value's bytes in `text`, [value_begin, value_end), trimmed
     *  (empty when the line states none: value_begin == value_end). */
    int value_begin;
    int value_end;
    /** FIELD: where "//" starts, -1 when the line has no note. */
    int note_at;
};

struct Editor_NpcStatsFile
{
    struct Editor_NpcStatsLine* lines;
    int line_count;
    int line_capacity;
    int final_newline;
};

/** The ledger's shard of `name`: its first byte lowercased, '_' when that is
 *  not a letter or digit. */
char
Editor_NpcStatsShard(const char* name);

/** 1 for a gameval the ledger can name a file after: 1..63 bytes of
 *  [A-Za-z0-9_]. */
int
Editor_NpcStatsNameValid(const char* name);

/** "stats:<shard>/<name>". The name must be valid. */
void
Editor_NpcStatsDocKey(
    char out[EDITOR_DOC_KEY_MAX],
    const char* name);

/** The ledger's path under the content dir, "npc_stats/<shard>/<name>.stats". */
void
Editor_NpcStatsPath(
    char* out,
    size_t out_size,
    const char* name);

void
Editor_NpcStatsInit(struct Editor_NpcStatsFile* file);

/** NULL-tolerant. */
void
Editor_NpcStatsFree(struct Editor_NpcStatsFile* file);

/** Parse, replacing what `file` held. Every text parses (a line that is not
 *  a field is text); NULL with length 0 is an empty file. */
void
Editor_NpcStatsParse(
    struct Editor_NpcStatsFile* file,
    const char* text,
    size_t length);

/** snprintf's sizing contract. */
size_t
Editor_NpcStatsEmit(
    const struct Editor_NpcStatsFile* file,
    char* out,
    size_t out_capacity);

/** Line index of the first field named `key`, or -1. */
int
Editor_NpcStatsFind(
    const struct Editor_NpcStatsFile* file,
    const char* key);

/** The value of `key` into `out` ("" when absent or "-"). 1 when the file
 *  states a value. */
int
Editor_NpcStatsGet(
    const struct Editor_NpcStatsFile* file,
    const char* key,
    char* out,
    size_t out_size);

/**
 * The ledger's text with `key` set to `value` ("" removes its line) and
 * `source = authored`. `old_text` may be empty (no ledger yet): the new file
 * is a header naming its writer, the source line and the key. Writes the new
 * text into `out` (snprintf's contract) and its length into `*out_length`.
 * Returns 1, or 0 -- nothing written -- when the key or value is not one a
 * ledger line can hold (a key with '=', a space or "//"; a value with "//"
 * or a line break).
 */
int
Editor_NpcStatsTextSet(
    const char* old_text,
    size_t old_length,
    const char* npc,
    const char* key,
    const char* value,
    char* out,
    size_t out_capacity,
    size_t* out_length);

/* ---- the Stats tab's keys and its derived cells ---------------------------------- */

/** The levels: `.npc` keys of their own (hitpoints=, attack=, ...). */
#define EDITOR_NPCSTATS_LEVELS 6
/** The bonuses: `param=<name>,<value>` on the npc record. */
#define EDITOR_NPCSTATS_BONUSES 13

/** "hitpoints", "attack", "strength", "defence", "magic", "ranged". */
const char*
Editor_NpcStatsLevelKey(int index);

/** "stabattack", "slashattack", "crushattack", "stabdefence", "slashdefence",
 *  "crushdefence", "strengthbonus", "rangeattack", "rangebonus",
 *  "magicattack", "magicdefence", "rangedefence", "magic_maxhit". */
const char*
Editor_NpcStatsBonusKey(int index);

/** What each derived cell's tooltip names (under 64 bytes: a tooltip's
 *  room, so none is cut). */
#define EDITOR_NPC_MELEE_MAXHIT_TIP "~npc_melee_maxhit: ((str + 9) * (bonus + 64) + 320) / 640"
#define EDITOR_NPC_RANGED_MAXHIT_TIP "~npc_ranged_maxhit: ((rng + 9) * (bonus + 64) + 320) / 640"
#define EDITOR_NPC_MAGIC_MAXHIT_TIP "~npc_generic_magicattack: the param magic_maxhit"
#define EDITOR_NPC_COMBAT_TIP "vislevel: (def+hp)/4 + 0.325*max(att+str,1.5*rng,1.5*mag)"

/**
 * The npc swing's max hit: ((level + 9) * (bonus + 64) + 320) / 640, the
 * effective level being the stat plus 9 (8 and the npc's +1 style) -- the
 * rule `~npc_melee_maxhit` (strength, strengthbonus) and `~npc_ranged_maxhit`
 * (ranged, rangebonus) apply, as the tree's own worked figures state it
 * (tools/generate_quest_combat_manifest.py: Sourhog 30 / 0 -> 4, the
 * Arzinian Avatar of Ranging 110 / 10 -> 14). Never below 0.
 */
int
Editor_NpcMaxHit(
    int level,
    int bonus);

/**
 * The combat level the cache's vislevel states, computed from the stats the
 * way ToriRSServer_CombatLevel (torirs_server_combat.c) computes a player's,
 * with no prayer: floor(0.25 * (defence + hitpoints) + 0.325 * max(attack +
 * strength, floor(1.5 * ranged), floor(1.5 * magic))), in integers.
 */
int
Editor_NpcCombatLevel(
    int attack,
    int strength,
    int defence,
    int hitpoints,
    int magic,
    int ranged);

#endif
